/* Jingxu integration over the pinned MIT FableCut editor. */
'use strict';
// Timeline dragging prevents the default pointer action; retain keyboard focus in this frame.
window.addEventListener('pointerdown',()=>window.focus(),true);
const studioParent=new URL(document.referrer||'http://127.0.0.1:8766').origin;
const studioPending=new Map();let studioClipboard=null;
function studioRequest(action,payload={}){if(parent===window)return Promise.reject(new Error('请从灵镜AI主窗口打开此功能'));return new Promise((resolve,reject)=>{const id=crypto.randomUUID();studioPending.set(id,{resolve,reject});parent.postMessage({studioEditor:true,id,action,payload},studioParent);setTimeout(()=>{if(studioPending.has(id)){studioPending.delete(id);reject(new Error('主工作台没有响应，请从灵镜AI打开剪辑。'));}},90000);});}
window.addEventListener('message',async e=>{if(e.source!==parent||e.origin!==studioParent||!e.data?.studioEditor)return;const d=e.data;if(d.reply){const p=studioPending.get(d.id);if(p){studioPending.delete(d.id);d.error?p.reject(new Error(d.error)):p.resolve(d.result);}return;}if(!['flush','pause','sync'].includes(d.action))return;try{let result;if(d.action==='flush')result=await studioFlush();if(d.action==='pause'){pause();result={exporting:state.exporting,dirty:studioDirty};}if(d.action==='sync'){await studioFlush();await syncFromServer(true);result=true;}parent.postMessage({studioEditor:true,id:d.id,reply:true,result},studioParent);}catch(error){parent.postMessage({studioEditor:true,id:d.id,reply:true,error:error.message},studioParent);}});
function studioButton(id,label,fn,parentEl){const b=document.createElement('button');b.id=id;b.className='btn tiny';b.textContent=label;b.onclick=()=>Promise.resolve(fn()).catch(e=>toast(e.message));(parentEl||document.querySelector('.timeline-tools')).appendChild(b);return b;}
const toolbar=document.querySelector('#btnSplit').parentElement;
function studioCopy(){const clips=withLinked(selectedClips());if(!clips.length)return toast('先选择片段');studioClipboard=structuredClone(clips);toast('已复制所选片段');}
function studioPaste(){if(!studioClipboard?.length)return;pushUndo();const first=Math.min(...studioClipboard.map(c=>c.start)),groups=new Map();const clips=structuredClone(studioClipboard).map(c=>{c.id='c_'+uid();c.start=Math.max(0,state.time+c.start-first);if(c.linkGroup){if(!groups.has(c.linkGroup))groups.set(c.linkGroup,'lg_'+uid());c.linkGroup=groups.get(c.linkGroup);}return c;});project.clips.push(...clips);setSelection(clips.map(c=>c.id));scheduleSave();rebuildClips();renderInspector();}
async function studioUnlink(){const clips=withLinked(selectedClips()).filter(c=>['video','audio'].includes(c.kind));if(!clips.length)return toast('先选择有声音的视频或音轨');const additions=[];for(const c of clips.filter(c=>c.kind==='video')){const linked=clips.some(a=>a.kind==='audio'&&((c.linkGroup&&a.linkGroup===c.linkGroup)||(a.mediaId===c.mediaId&&Math.abs(a.start-c.start)<.001)));if(!linked){try{const audio=await getAudioBuffer(getMedia(c.mediaId));if(audio?.length)additions.push({original:c,clip:{...structuredClone(c),id:'c_'+uid(),kind:'audio',track:audioTrackIds()[0]||'A1',name:c.name+' · 分离音轨',props:{...c.props,studioUnlinked:true}}});}catch{}}}if(!additions.length&&!clips.some(c=>c.kind==='audio'))return toast('该视频没有可分离的音轨');pushUndo();for(const a of additions){a.original.props.volume=0;project.clips.push(a.clip);clips.push(a.clip);}for(const c of clips){c.props={...c.props,studioUnlinked:true};delete c.linkGroup;delete c.linkedId;}setSelection([clips[0].id]);scheduleSave();rebuildClips();renderInspector();toast('已解除音画关联，可分别移动和剪切');}
studioButton('studioCopy','复制',studioCopy,toolbar);studioButton('studioPaste','粘贴',studioPaste,toolbar);studioButton('studioUnlink','音画分离',studioUnlink,toolbar);studioButton('studioUndo','撤销',undo,toolbar);studioButton('studioRedo','重做',redo,toolbar);
window.addEventListener('keydown',e=>{if(isTypingTarget(document.activeElement))return;const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();let handled=true;if(mod&&key==='c')studioCopy();else if(mod&&key==='v')studioPaste();else if(mod&&key==='x'){studioCopy();deleteSelected();}else if(mod&&key==='b')splitAtPlayhead();else if(mod&&key==='s')studioFlush().then(()=>toast('剪辑已保存')).catch(e=>toast(e.message));else if(mod&&key==='d'&&!e.altKey){studioApplyEffect('dissolve');}else handled=false;if(handled){e.preventDefault();e.stopImmediatePropagation();}},true);
const studioTopActions=document.querySelector('.topbar-right');
studioButton('studioMaterials','项目素材',()=>studioRequest('materials'),studioTopActions);
studioButton('studioLibrary','个人资料库',()=>studioRequest('library'),studioTopActions);
studioButton('studioProxy','流畅预览',async()=>{const ids=[...selectedMediaIds()];const chosen=ids.length?project.media.filter(m=>ids.includes(m.id)&&m.kind==='video'):project.media.filter(m=>m.kind==='video');if(!chosen.length)return toast('先选择或导入视频');await studioFlush();for(const m of chosen){await studioRequest('proxy',{assetId:m.id});}toast('正在生成720p预览代理，原始素材用于导出。');const waiting=new Set(chosen.map(m=>m.id));const timer=setInterval(async()=>{try{const {jobs}=await studioRequest('proxies');for(const j of jobs){if(!waiting.has(j.assetId))continue;if(j.status==='failed'){waiting.delete(j.assetId);toast(j.error);}if(j.status==='succeeded'){const m=getMedia(j.assetId);if(m)m.previewSrc=j.src;waiting.delete(j.assetId);}}if(!waiting.size){clearInterval(timer);scheduleSave();toast('流畅预览代理已就绪');}}catch(e){clearInterval(timer);toast(e.message);}},1500);},studioTopActions);
studioButton('studioCaptions','自动字幕',async()=>{
 await studioFlush();pause();const duration=projDur();if(duration<=0)return toast('时间线还没有内容');if(duration>1800)return toast('请先按30分钟以内分段识别字幕');
 const dialog=document.createElement('dialog');dialog.className='studio-caption-dialog';dialog.innerHTML='<h2>自动字幕</h2><p>识别当前时间线的声音，结果可在画面中拖动和编辑。</p><label>放置位置<select id="captionPosition"><option value="bottom">画面底部</option><option value="center">画面中间</option><option value="top">画面顶部</option></select></label><label>语种<select id="captionLanguage"><option value="zh">中文</option><option value="auto">自动识别</option><option value="en">English</option></select></label><label><input type="checkbox" id="captionReplace" checked>替换已有自动字幕（保留手工文字）</label><p id="captionStatus"></p><div class="caption-actions"><button id="captionClose">关闭</button><button id="captionGo">识别字幕</button><button id="captionApply" disabled>应用到时间线</button></div>';document.body.appendChild(dialog);dialog.showModal();
 const status=dialog.querySelector('#captionStatus'),start=dialog.querySelector('#captionGo'),apply=dialog.querySelector('#captionApply');let jobId=null,startedRevision=null;
 dialog.querySelector('#captionClose').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());
 start.onclick=async()=>{start.disabled=true;try{await studioFlush();startedRevision=project.revision;status.textContent='正在准备识别音轨…';const wav=await renderAudioMix(0,duration);if(!wav)throw new Error('当前时间线没有可识别的声音');const uploaded=await fetch('/api/upload?name='+encodeURIComponent('captions-'+Date.now()+'.wav'),{method:'POST',body:wav}).then(r=>r.json());if(!uploaded.src)throw new Error(uploaded.error||'音轨准备失败');const job=await studioRequest('captions',{src:uploaded.src,language:dialog.querySelector('#captionLanguage').value,requestId:'caption-'+crypto.randomUUID()});jobId=job.id;status.textContent='正在本机识别…';const poll=setInterval(async()=>{try{const result=await studioRequest('caption-status',{jobId});if(result.status==='failed')throw new Error(result.error);if(result.status==='succeeded'){clearInterval(poll);status.textContent=result.transcript?.text||'识别完成';apply.disabled=false;}else status.textContent=result.stage||'正在识别…';}catch(e){clearInterval(poll);status.textContent=e.message;start.disabled=false;}},1500);}catch(e){status.textContent=e.message;start.disabled=false;}};
 apply.onclick=async()=>{apply.disabled=true;try{await studioFlush();if(project.revision!==startedRevision){status.textContent='时间线已改变，请核对识别稿；点击再次应用会使用当前时间线。';startedRevision=project.revision;apply.disabled=false;return;}await studioRequest('apply-captions',{jobId,revision:project.revision,position:dialog.querySelector('#captionPosition').value,replaceAuto:dialog.querySelector('#captionReplace').checked});await syncFromServer(true);dialog.close();toast('字幕已作为文字片段加入，可拖动画面中的字幕位置');}catch(e){status.textContent=e.message;apply.disabled=false;}};
},studioTopActions);
// Register completed exports back in the current Jingxu workspace.
const studioFetch=window.fetch.bind(window);window.fetch=async(...args)=>{const response=await studioFetch(...args);if(String(args[0]).startsWith('/api/export/end')&&!String(args[0]).includes('discard'))response.clone().json().then(d=>{if(d.src)studioRequest('recover',{name:d.src}).then(()=>toast('成片已回到项目资源库')).catch(e=>toast(e.message));}).catch(()=>{});return response;};
// Recover a retained local draft only after a deliberate user choice.
setTimeout(()=>{const raw=localStorage.getItem('jingxu-editor-draft:'+location.port);if(raw&&confirm('检测到上次未保存的剪辑草稿，是否恢复到编辑器中？')){try{const d=JSON.parse(raw);d.revision=project.revision;applyProject(d);scheduleSave();}catch(e){toast('草稿无法读取：'+e.message);}}},1200);
if(parent!==window)setInterval(()=>parent.postMessage({studioEditor:true,event:'status',dirty:studioDirty,exporting:state.exporting,revision:project.revision},studioParent),700);
studioButton('studioDraft','导出草稿',()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(projectJSON(),null,2)],{type:'application/json'}));a.download='jingxu-edit-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);},document.querySelector('#settingsOverlay .dialog-actions')||studioTopActions);
